-- Guards: the auth columns this script writes exist; no seed email/id belongs to another account.
do $$
declare v_missing text;
begin
  select string_agg(c, ', ') into v_missing
  from unnest(array['instance_id','id','aud','role','email','encrypted_password','email_confirmed_at',
                    'confirmation_token','recovery_token','email_change_token_new','email_change',
                    'email_change_token_current','phone_change','phone_change_token','reauthentication_token',
                    'raw_app_meta_data','raw_user_meta_data','is_super_admin','created_at','updated_at',
                    'is_sso_user','is_anonymous']) c
  where not exists (select 1 from information_schema.columns
                    where table_schema = 'auth' and table_name = 'users' and column_name = c);
  if v_missing is not null then raise exception 'auth.users is missing expected columns: %', v_missing; end if;
  select string_agg(c, ', ') into v_missing
  from unnest(array['id','provider_id','user_id','identity_data','provider','last_sign_in_at','created_at','updated_at']) c
  where not exists (select 1 from information_schema.columns
                    where table_schema = 'auth' and table_name = 'identities' and column_name = c);
  if v_missing is not null then raise exception 'auth.identities is missing expected columns: %', v_missing; end if;
  if exists (select 1 from auth.users u join _seed_users s on lower(u.email) = lower(s.email) and u.id <> s.id)
     or exists (select 1 from auth.users u join _seed_users s on u.id = s.id and lower(u.email) <> lower(s.email))
     or exists (select 1 from public.profiles p join _seed_users s on lower(p.email) = lower(s.email) and p.id <> s.id) then
    raise exception 'A seed email or id is already used by a different account - aborting, nothing written.';
  end if;
end $$;

-- The only statement that contains the password: a plain INSERT (pg_stat_statements stores it
-- parameterised). Each login account gets its own bcrypt salt (cost 10, as Supabase Auth uses).
with pw(v) as (select '__SET_TEST_PASSWORD_HERE__'::text)
insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  confirmation_token, recovery_token, email_change_token_new, email_change,
  email_change_token_current, phone_change, phone_change_token, reauthentication_token,
  raw_app_meta_data, raw_user_meta_data, is_super_admin, created_at, updated_at,
  is_sso_user, is_anonymous)
select '00000000-0000-0000-0000-000000000000'::uuid, s.id, 'authenticated', 'authenticated', s.email,
       case when s.can_login then extensions.crypt(pw.v, extensions.gen_salt('bf', 10)) else '' end,
       now(), '', '', '', '', '', '', '', '',
       '{"provider": "email", "providers": ["email"]}'::jsonb, s.meta, false, now(), now(), false, false
from _seed_users s cross join pw
order by s.id
on conflict (id) do nothing;

insert into auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
select s.identity_id, s.id::text, s.id,
       jsonb_build_object('sub', s.id::text, 'email', s.email, 'email_verified', true, 'phone_verified', false),
       'email', null, now(), now()
from _seed_users s
order by s.id
on conflict (provider_id, provider) do nothing;

-- Post-checks (an exception rolls everything back): placeholder replaced, triggers provisioned.
do $$
declare v_bad text;
begin
  if exists (select 1 from auth.users u join _seed_users s on s.id = u.id
             where case when u.encrypted_password like '$2%' -- bcrypt hashes only ('' would be an invalid salt)
                        then u.encrypted_password = extensions.crypt('__SET_TEST_PASSWORD_HERE__', u.encrypted_password) else false end) then
    raise exception 'The test password placeholder was not replaced - aborting, nothing written.';
  end if;
  select string_agg(s.email, ', ') into v_bad from _seed_users s
  where not exists (select 1 from auth.identities i where i.user_id = s.id and i.provider = 'email')
     or not exists (select 1 from public.profiles p where p.id = s.id)
     or not exists (select 1 from public.user_settings us where us.user_id = s.id);
  if v_bad is not null then raise exception 'Provisioning incomplete for: %', v_bad; end if;
  raise notice 'seed auth users present: % (login-enabled: %)',
    (select count(*) from auth.users u join _seed_users s on s.id = u.id),
    (select count(*) from auth.users u join _seed_users s on s.id = u.id where u.encrypted_password <> '');
end $$;

commit;
